import React, { useState } from 'react';
import {
  Box,
  Button,
  TextField,
  Typography,
  IconButton,
  Paper,
  Divider,
  Avatar
} from '@mui/material';
import { Add as AddIcon, Close as CloseIcon } from '@mui/icons-material';
import api from '../utils/api';

const PollForm = ({ onPollCreated, onCancel }) => {
  const [question, setQuestion] = useState('');
  const [options, setOptions] = useState(['', '']);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const handleAddOption = () => {
    if (options.length < 5) {
      setOptions([...options, '']);
    }
  };

  const handleOptionChange = (index, value) => {
    const newOptions = [...options];
    newOptions[index] = value;
    setOptions(newOptions);
  };

  const handleRemoveOption = (index) => {
    if (options.length > 2) {
      const newOptions = options.filter((_, i) => i !== index);
      setOptions(newOptions);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    if (!question.trim()) {
      setError('Please enter a question');
      return;
    }

    const validOptions = options.filter(opt => opt.trim() !== '');
    if (validOptions.length < 2) {
      setError('Please add at least 2 options');
      return;
    }

    try {
      setIsSubmitting(true);
      setError('');
      
      const pollData = {
        question,
        options: validOptions.map(opt => ({ text: opt })),
      };

      const response = await api.post('/polls', pollData);
      onPollCreated?.(response.data);
      
      // Reset form
      setQuestion('');
      setOptions(['', '']);
    } catch (err) {
      console.error('Error creating poll:', err);
      setError(err.response?.data?.message || 'Failed to create poll');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Paper elevation={2} sx={{ p: 2, mb: 2 }}>
      <Box display="flex" alignItems="center" mb={2}>
        <Avatar />
        <Typography variant="subtitle2" sx={{ ml: 1 }}>Create a Poll</Typography>
      </Box>
      
      <form onSubmit={handleSubmit}>
        <TextField
          fullWidth
          variant="outlined"
          label="Ask a question"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          margin="normal"
          required
        />
        
        <Typography variant="subtitle2" sx={{ mt: 2, mb: 1 }}>Options:</Typography>
        
        {options.map((option, index) => (
          <Box key={index} display="flex" alignItems="center" mb={1}>
            <TextField
              fullWidth
              variant="outlined"
              size="small"
              placeholder={`Option ${index + 1}`}
              value={option}
              onChange={(e) => handleOptionChange(index, e.target.value)}
              sx={{ flexGrow: 1 }}
              required={index < 2}
            />
            {options.length > 2 && (
              <IconButton 
                size="small" 
                onClick={() => handleRemoveOption(index)}
                sx={{ ml: 1 }}
              >
                <CloseIcon fontSize="small" />
              </IconButton>
            )}
          </Box>
        ))}
        
        {options.length < 5 && (
          <Button
            startIcon={<AddIcon />}
            onClick={handleAddOption}
            size="small"
            sx={{ mt: 1 }}
          >
            Add Option
          </Button>
        )}
        
        {error && (
          <Typography color="error" variant="body2" sx={{ mt: 1 }}>
            {error}
          </Typography>
        )}
        
        <Box display="flex" justifyContent="flex-end" mt={2}>
          <Button 
            onClick={onCancel}
            sx={{ mr: 1 }}
            disabled={isSubmitting}
          >
            Cancel
          </Button>
          <Button 
            type="submit" 
            variant="contained" 
            color="primary"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Creating...' : 'Create Poll'}
          </Button>
        </Box>
      </form>
    </Paper>
  );
};

export default PollForm;
